{"path": "/home/hshen/posttrain_v4flash/pipelines/kernel_translate/corpus.py", "content": """"CUDA kernel source corpus loader for the kernel-translate pipelines
(plan doc §2 extension: CUDA->Triton translation pairs + CUDA->SYCL XPU ports).

Unified abstraction:

  KernelRecord:
    source_lang     "cuda" | "pytorch"   -- language of source_code
    source_code     the kernel source handed to the teacher for translation
    reference_code  executable PyTorch oracle for the same computation:
                    either defines ref_fn(*inputs), or KernelBench-style
                    Model / get_inputs() / get_init_inputs()
    task_name       unique-ish name, e.g. "sakana_l1_t1_matmul" | "vector_add"
    meta            provenance + optional "input_gen" source (gen_inputs
                    contract, see cuda_kernel/tasks.py) and optional
                    "triton_code" exemplar target

Corpora (--corpus names):
  kernelbook  GPUMODE/KernelBook: 18K real-project PyTorch<->Triton pairs
              (inductor-generated Triton). source_lang="pytorch" -- these are
              NOT CUDA sources, so they do not feed the cuda2* directions
              directly; they are parsed into records for provenance and used
              as few-shot translation exemplars (meta["triton_code"]).
              File: dataset_permissive.parquet (~87 MB).
  sakana      SakanaAI/AI-CUDA-Engineer-Archive: ~30K PyTorch->CUDA pairs with
              compile/correctness/speedup metadata. source_lang="cuda".
              NOTE: the full archive is 3 parquet shards (~65 MB total:
              level_1 12157 rows, level_2 12938, level_3 5520). To keep the
              local checkout small we download ONLY level_1 by default; pass
              shards=("level_1", "level_2", "level_3") to load_sakana() (and
              re-run with download enabled) for the full archive.
  builtin     5 hand-written CUDA kernels (vector_add, sgemv, reduce_sum,
              histogram, conv1d) with ref_fn + gen_inputs oracles. Always
              available -- the pipelines keep working when downloads fail.

Downloads use the `hf` CLI (available on this host) into data/corpus/:
  hf download <repo> --repo-type dataset --include <pattern> --local-dir <dir>

CLI:
  python corpus.py --corpus kernelbook --limit 5      # download if needed, print stats
  python corpus.py --corpus sakana --limit 5
  python corpus.py --corpus builtin
  python corpus.py --corpus sakana --no-download      # fail if not on disk
"""
from __future__ import annotations

import argparse
import shutil
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parents[2]
DEFAULT_DATA_ROOT = PROJECT_ROOT / "data" / "corpus"

KERNELBOOK_REPO = "GPUMODE/KernelBook"
KERNELBOOK_FILE = "dataset_permissive.parquet"
SAKANA_REPO = "SakanaAI/AI-CUDA-Engineer-Archive"
SAKANA_DEFAULT_SHARDS = ("level_1",)  # see module docstring: level_2/3 add ~18K rows
SAKANA_ALL_SHARDS = ("level_1", "level_2", "level_3")


class CorpusError(RuntimeError):
    """Raised when a corpus cannot be downloaded or parsed."""


@dataclass
class KernelRecord:
    source_lang: str
    source_code: str
    reference_code: str
    task_name: str
    meta: dict = field(default_factory=dict)


# ---------------------------------------------------------------------------
# Download helper (hf CLI on PATH; no system packages required)
# ---------------------------------------------------------------------------

def hf_download(repo: str, include: str, local_dir: Path) -> Path:
    """Download one file pattern from a HF dataset repo via the hf CLI."""
    if shutil.which("hf") is None:
        raise CorpusError("hf CLI not found on PATH; cannot download " + repo)
    local_dir.mkdir(parents=True, exist_ok=True)
    cmd = ["hf", "download", repo, "--repo-type", "dataset",
           "--include", include, "--local-dir", str(local_dir)]
    proc = subprocess.run(cmd, capture_output=True, text=True, timeout=3600)
    if proc.returncode != 0:
        raise CorpusError(
            f"hf download {repo} ({include}) failed:\n{(proc.stderr or proc.stdout)[-1000:]}")
    return local_dir


# ---------------------------------------------------------------------------
# GPUMODE/KernelBook
# ---------------------------------------------------------------------------

def load_kernelbook(limit: int = 0, *, data_root: Path = DEFAULT_DATA_ROOT,
                    download: bool = True) -> list[KernelRecord]:
    """Parse KernelBook into records (source_lang="pytorch").

    Columns: entry_point, python_code, triton_code, original_triton_code,
    repo_name, module_name, synthetic, uuid, licenses, stars, sha, repo_link.
    """
    path = Path(data_root) / "kernelbook" / KERNELBOOK_FILE
    if not path.exists():
        if not download:
            raise CorpusError(f"{path} not on disk and download disabled")
        hf_download(KERNELBOOK_REPO, KERNELBOOK_FILE, path.parent)
    try:
        import pandas as pd
    except ImportError as e:
        raise CorpusError("pandas/pyarrow required: uv pip install --python "
                          "<venv>/bin/python pandas pyarrow") from e
    df = pd.read_parquet(path)
    records: list[KernelRecord] = []
    for _, row in df.iterrows():
        py_code = str(row["python_code"] or "")
        tri_code = str(row["triton_code"] or "")
        if not py_code.strip() or not tri_code.strip():
            continue
        records.append(KernelRecord(
            source_lang="pytorch",
            source_code=py_code,
            reference_code=py_code,  # the PyTorch module is its own oracle
            task_name=f"kernelbook_{row['module_name']}_{row['uuid']}",
            meta={
                "corpus": "kernelbook",
                "triton_code": tri_code,  # inductor-generated target (exemplar)
                "entry_point": str(row["entry_point"]),
                "repo_name": str(row["repo_name"]),
                "repo_link": str(row["repo_link"]),
                "licenses": str(row["licenses"]),
                "stars": int(row["stars"]),
            },
        ))
        if limit and len(records) >= limit:
            break
    return records


# ---------------------------------------------------------------------------
# SakanaAI/AI-CUDA-Engineer-Archive
# ---------------------------------------------------------------------------

def load_sakana(limit: int = 0, *, data_root: Path = DEFAULT_DATA_ROOT,
                download: bool = True, shards: tuple[str, ...] = SAKANA_DEFAULT_SHARDS,
                correct_only: bool = True) -> list[KernelRecord]:
    """Parse the AI-CUDA-Engineer archive into records (source_lang="cuda").

    Only rows with Correct == True become records by default (the archive also
    ships failing kernels with error logs; those fit a repair pipeline, not
    translation). reference_code is PyTorch_Code_Module (KernelBench-style:
    Model + get_inputs + get_init_inputs).
    """
    try:
        import pandas as pd
    except ImportError as e:
        raise CorpusError("pandas/pyarrow required: uv pip install --python "
                          "<venv>/bin/python pandas pyarrow") from e
    base = Path(data_root) / "sakana"
    frames = []
    for shard in shards:
        path = base / f"{shard}.parquet"
        if not path.exists():
            if not download:
                raise CorpusError(f"{path} not on disk and download disabled")
            hf_download(SAKANA_REPO, f"{shard}.parquet", base)
        frames.append(pd.read_parquet(path))
    df = frames[0] if len(frames) == 1 else pd.concat(frames, ignore_index=True)
    if correct_only:
        df = df[df["Correct"] == True]  # noqa: E712 (pandas boolean column)
    records: list[KernelRecord] = []
    for _, row in df.iterrows():
        cuda_code = str(row["CUDA_Code"] or "")
        ref_code = str(row["PyTorch_Code_Module"] or "")
        if not cuda_code.strip() or not ref_code.strip():
            continue
        op = str(row["Op_Name"]).strip().replace(" ", "_") or "unnamed"
        records.append(KernelRecord(
            source_lang="cuda",
            source_code=cuda_code,
            reference_code=ref_code,
            task_name=f"sakana_l{int(row['Level_ID'])}_t{int(row['Task_ID'])}_{op}",
            meta={
                "corpus": "sakana",
                "level_id": int(row["Level_ID"]),
                "task_id": int(row["Task_ID"]),
                "kernel_name": str(row["Kernel_Name"]),
                "cuda_speedup_native": float(row["CUDA_Speedup_Native"]),
                "cuda_speedup_compile": float(row["CUDA_Speedup_Compile"]),
                "max_diff": float(row["Max_Diff"]),
                # archive input contract: get_inputs() lives inside reference_code
                "input_mode": "get_inputs",
            },
        ))
        if limit and len(records) >= limit:
            break
    return records


# ---------------------------------------------------------------------------
# Built-in hand-written CUDA samples (always available)
# ---------------------------------------------------------------------------

_VECADD_CUDA = r"""// vector_add: C[i] = A[i] + B[i] for i in [0, n)
#include <cuda_runtime.h>

__global__ void vector_add_kernel(const float* __restrict__ A,
                                  const float* __restrict__ B,
                                  float* __restrict__ C, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        C[i] = A[i] + B[i];
    }
}

void vector_add(const float* A, const float* B, float* C, int n) {
    int threads = 256;
    int blocks = (n + threads - 1) / threads;
    vector_add_kernel<<<blocks, threads>>>(A, B, C, n);
}
"""

_VECADD_REF = '''\
import torch

def ref_fn(a, b):
    return a + b
'''

_VECADD_GEN = '''\
import torch

def gen_inputs(seed, device, dtype):
    sizes = [1024, 4097, 65536, 100003]   # non-multiples of 256 exercise tail masking
    n = sizes[seed % len(sizes)]
    g = torch.Generator(device=device)
    g.manual_seed(seed * 7919 + 3)
    a = torch.randn(n, generator=g, device=device, dtype=dtype)
    b = torch.randn(n, generator=g, device=device, dtype=dtype)
    return (a, b)
'''

_SGEMV_CUDA = r"""// sgemv: y = A @ x, A is (m, n) row-major. One thread per row.
#include <cuda_runtime.h>

__global__ void sgemv_kernel(const float* __restrict__ A,
                             const float* __restrict__ x,
                             float* __restrict__ y, int m, int n) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < m) {
        float acc = 0.0f;
        for (int j = 0; j < n; ++j) {
            acc += A[row * n + j] * x[j];
        }
        y[row] = acc;
    }
}

void sgemv(const float* A, const float* x, float* y, int m, int n) {
    int threads = 128;
    int blocks = (m + threads - 1) / threads;
    sgemv_kernel<<<blocks, threads>>>(A, x, y, m, n);
}
"""

_SGEMV_REF = '''\
import torch

def ref_fn(a, x):
    return a @ x
'''

_SGEMV_GEN = '''\
import torch

def gen_inputs(seed, device, dtype):
    shapes = [(256, 256), (512, 384), (1024, 768), (300, 511)]
    m, n = shapes[seed % len(shapes)]
    g = torch.Generator(device=device)
    g.manual_seed(seed * 7919 + 5)
    a = torch.randn(m, n, generator=g, device=device, dtype=dtype)
    x = torch.randn(n, generator=g, device=device, dtype=dtype)
    return (a, x)
'''

_REDUCE_CUDA = r"""// reduce_sum: out[0] = sum_i X[i]. Block reduction + atomic accumulate.
#include <cuda_runtime.h>

__global__ void reduce_sum_kernel(const float* __restrict__ X,
                                  float* __restrict__ out, int n) {
    __shared__ float sdata[256];
    int tid = threadIdx.x;
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    sdata[tid] = (i < n) ? X[i] : 0.0f;
    __syncthreads();
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }
    if (tid == 0) {
        atomicAdd(out, sdata[0]);
    }
}

void reduce_sum(const float* X, float* out, int n) {
    int threads = 256;
    int blocks = (n + threads - 1) / threads;
    reduce_sum_kernel<<<blocks, threads>>>(X, out, n);
}
"""

_REDUCE_REF = '''\
import torch

def ref_fn(x):
    return x.sum()
'''

_REDUCE_GEN = '''\
import torch

def gen_inputs(seed, device, dtype):
    sizes = [4096, 100003, 262144, 65537]
    n = sizes[seed % len(sizes)]
    g = torch.Generator(device=device)
    g.manual_seed(seed * 7919 + 7)
    x = torch.randn(n, generator=g, device=device, dtype=dtype)
    return (x,)
'''

_HIST_CUDA = r"""// histogram: hist[v] = count of X[i] == v, for integer values in [0, bins).
#include <cuda_runtime.h>

__global__ void histogram_kernel(const int* __restrict__ X,
                                 int* __restrict__ hist, int n, int bins) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        int v = X[i];
        if (v >= 0 && v < bins) {
            atomicAdd(&hist[v], 1);
        }
    }
}

void histogram(const int* X, int* hist, int n, int bins) {
    int threads = 256;
    int blocks = (n + threads - 1) / threads;
    histogram_kernel<<<blocks, threads>>>(X, hist, n, bins);
}
"""

_HIST_REF = '''\
import torch

def ref_fn(x, bins):
    return torch.bincount(x, minlength=bins)
'''

_HIST_GEN = '''\
import torch

def gen_inputs(seed, device, dtype):
    sizes = [4096, 100003, 262144, 65537]
    bins_list = [64, 128, 96, 256]
    n = sizes[seed % len(sizes)]
    bins = bins_list[seed % len(bins_list)]
    g = torch.Generator(device=device)
    g.manual_seed(seed * 7919 + 11)
    x = torch.randint(0, bins, (n,), generator=g, device=device)
    return (x, bins)
'''

_CONV1D_CUDA = r"""// conv1d: valid cross-correlation. out[i] = sum_j X[i+j] * W[j],
// X is (n,), W is (k,), out is (n - k + 1,).
#include <cuda_runtime.h>

__global__ void conv1d_kernel(const float* __restrict__ X,
                              const float* __restrict__ W,
                              float* __restrict__ out, int n, int k) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    int m = n - k + 1;
    if (i < m) {
        float acc = 0.0f;
        for (int j = 0; j < k; ++j) {
            acc += X[i + j] * W[j];
        }
        out[i] = acc;
    }
}

void conv1d(const float* X, const float* W, float* out, int n, int k) {
    int m = n - k + 1;
    int threads = 256;
    int blocks = (m + threads - 1) / threads;
    conv1d_kernel<<<blocks, threads>>>(X, W, out, n, k);
}
"""

_CONV1D_REF = '''\
import torch
import torch.nn.functional as F

def ref_fn(x, w):
    return F.conv1d(x.view(1, 1, -1), w.view(1, 1, -1)).view(-1)
'''

_CONV1D_GEN = '''\
import torch

def gen_inputs(seed, device, dtype):
    shapes = [(4096, 7), (65536, 15), (100003, 31), (8192, 63)]
    n, k = shapes[seed % len(shapes)]
    g = torch.Generator(device=device)
    g.manual_seed(seed * 7919 + 13)
    x = torch.randn(n, generator=g, device=device, dtype=dtype)
    w = torch.randn(k, generator=g, device=device, dtype=dtype)
    return (x, w)
'''

_BUILTIN = [
    ("vector_add", "easy",
     "Elementwise vector addition C = A + B over n floats.",
     _VECADD_CUDA, _VECADD_REF, _VECADD_GEN),
    ("sgemv", "easy",
     "Dense matrix-vector product y = A @ x, A row-major (m, n), one thread per row.",
     _SGEMV_CUDA, _SGEMV_REF, _SGEMV_GEN),
    ("reduce_sum", "medium",
     "Full reduction of a float vector to a scalar via block reduction + atomicAdd.",
     _REDUCE_CUDA, _REDUCE_REF, _REDUCE_GEN),
    ("histogram", "medium",
     "Integer histogram over values in [0, bins) via global atomicAdd.",
     _HIST_CUDA, _HIST_REF, _HIST_GEN),
    ("conv1d", "medium",
     "Valid 1D cross-correlation of a signal with a small kernel.",
     _CONV1D_CUDA, _CONV1D_REF, _CONV1D_GEN),
]


def load_builtin() -> list[KernelRecord]:
    records = []
    for name, difficulty, desc, cuda_src, ref_src, gen_src in _BUILTIN:
        records.append(KernelRecord(
            source_lang="cuda",
            source_code=cuda_src,
            reference_code=ref_src,
            task_name=f"builtin_{name}",
            meta={
                "corpus": "builtin",
                "difficulty": difficulty,
                "description": desc,
                "input_gen": gen_src,      # gen_inputs(seed, device, dtype) contract
                "input_mode": "gen_inputs",
            },
        ))
    return records


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

LOADERS = {
    "kernelbook": load_kernelbook,
    "sakana": load_sakana,
    "builtin": lambda limit=0, **_: load_builtin(),
}


def load_corpus(name: str, limit: int = 0, **kw) -> list[KernelRecord]:
    if name not in LOADERS:
        raise CorpusError(f"unknown corpus {name!r}; available: {sorted(LOADERS)}")
    return LOADERS[name](limit, **kw)


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--corpus", required=True, choices=sorted(LOADERS))
    ap.add_argument("--limit", type=int, default=0)
    ap.add_argument("--no-download", action="store_true",
                    help="fail instead of downloading when files are missing")
    ap.add_argument("--preview", type=int, default=0,
                    help="print source/reference preview of the first N records")
    args = ap.parse_args()

    kw = {} if args.corpus == "builtin" else {"download": not args.no_download}
    try:
        records = load_corpus(args.corpus, args.limit, **kw)
    except CorpusError as e:
        print(f"[corpus ERROR] {e}", file=sys.stderr)
        sys.exit(1)

    print(f"corpus={args.corpus} records={len(records)}")
    langs: dict[str, int] = {}
    for r in records:
        langs[r.source_lang] = langs.get(r.source_lang, 0) + 1
    print(f"source_langs={langs}")
    for r in records[: args.preview]:
        print(f"--- {r.task_name} ({r.source_lang}) meta_keys={sorted(r.meta)}")
        print("source:", r.source_code[:300].replace("\n", " | "))
        print("reference:", r.reference_code[:200].replace("\n", " | "))


if __name__ == "__main__":
    main()
"}

{"content": """"Staged SYCL verification for CUDA->SYCL translations (plan doc §2 extension).

  L0  static check (pure python, runs on this login node):
        - must use SYCL 2020 constructs (sycl:: namespace, sycl::queue,
          parallel_for, an int main() self-test);
        - must NOT retain CUDA constructs (__global__, cudaMalloc, blockIdx,
          threadIdx, <<< >>> launches, ...);
        - crude syntactic sanity: balanced () / {} / [] after stripping
          comments and string/char literals, plus a minimum semicolon count.
  L1  compile + run the self-test with a SYCL toolchain. Enabled only when
      `icpx -fsycl`, `dpcpp`, or `clang++ -fsycl` is found on PATH; otherwise
      every L1 result is {"passed": None, "status": "sycl_toolchain_missing"}
      so the caller records and skips -- same pattern as rtl/verify.py's
      iverilog_missing. This host has no oneAPI installed, so L1 is expected
      to report sycl_toolchain_missing here; the interface is cluster-ready.

Pass criterion for a translation: L0 passed AND (L1 passed OR L1 skipped as
sycl_toolchain_missing). If a toolchain IS present and L1 fails, the
translation is rejected.

CLI:
  python sycl_verify.py kernel.cpp          # L0 (+ L1 if toolchain present)
"""
from __future__ import annotations

import argparse
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

# CUDA constructs that must not survive a CUDA->SYCL port (word-boundary matched)
_CUDA_TOKENS = [
    "__global__", "__device__", "__host__", "__shared__", "__constant__",
    "__syncthreads", "__syncwarp", "__forceinline__",
    "blockIdx", "threadIdx", "blockDim", "gridDim", "warpSize",
    "cudaMalloc", "cudaFree", "cudaMemcpy", "cudaMemset", "cudaDeviceSynchronize",
    "cudaGetLastError", "cudaError_t", "cudaSuccess", "cudaStream_t",
    "cudaEvent_t", "cudaOccupancyMaxPotentialBlockSize",
]
_CUDA_TOKEN_RE = re.compile(r"\b(" + "|".join(re.escape(t) for t in _CUDA_TOKENS) + r")\b")
_CUDA_LAUNCH_RE = re.compile(r"<<<[^>]*>>>")  # triple-chevron kernel launch

# SYCL 2020 constructs expected in an Intel-XPU-style port
_SYCL_REQUIRED = ["sycl::queue", "parallel_for", "int main"]
_SYCL_NAMESPACE_MIN = 3  # minimum number of `sycl::` qualifications

_TOOLCHAIN_CANDIDATES = [
    ("icpx", ["icpx", "-fsycl"]),
    ("dpcpp", ["dpcpp"]),
    ("clang++", ["clang++", "-fsycl"]),
]


def _strip_comments_and_literals(src: str) -> str:
    """Remove // and /* */ comments and string/char literals (crude but
    sufficient for bracket-balance checks)."""
    out = []
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        two = src[i:i + 2]
        if two == "//":
            j = src.find("\n", i)
            i = n if j < 0 else j
        elif two == "/*":
            j = src.find("*/", i + 2)
            i = n if j < 0 else j + 2
        elif c in "\"'":
            j = i + 1
            while j < n and src[j] != c:
                j += 2 if src[j] == "\\" else 1
            i = j + 1
        else:
            out.append(c)
            i += 1
    return "".join(out)


def check_l0(src: str) -> dict:
    """Static check. Returns {"level": "L0", "passed": bool, "errors": [...]}."""
    errors: list[str] = []

    stripped = _strip_comments_and_literals(src)

    # -- required SYCL constructs ------------------------------------------
    for token in _SYCL_REQUIRED:
        if token not in stripped:
            errors.append(f"missing required SYCL construct: {token!r}")
    n_sycl = stripped.count("sycl::")
    if n_sycl < _SYCL_NAMESPACE_MIN:
        errors.append(f"only {n_sycl} `sycl::` qualifications "
                      f"(need >= {_SYCL_NAMESPACE_MIN}); is this really SYCL?")

    # -- forbidden CUDA leftovers -------------------------------------------
    for m in _CUDA_TOKEN_RE.finditer(stripped):
        errors.append(f"CUDA construct retained: {m.group(1)!r}")
    if _CUDA_LAUNCH_RE.search(stripped):
        errors.append("CUDA triple-chevron launch syntax <<< >>> retained")

    # -- crude syntax sanity: bracket balance + semicolons -------------------
    pairs = {"(": ")", "{": "}", "[": "]"}
    for op, cl in pairs.items():
        if stripped.count(op) != stripped.count(cl):
            errors.append(f"unbalanced {op}{cl}: {stripped.count(op)} vs "
                          f"{stripped.count(cl)}")
    if stripped.count(";") < 3:
        errors.append("suspiciously few semicolons (<3); probably not C++")

    # dedupe while preserving order
    seen, uniq = set(), []
    for e in errors:
        if e not in seen:
            seen.add(e)
            uniq.append(e)
    return {"level": "L0", "passed": not uniq, "errors": uniq}


def sycl_toolchain() -> list[str] | None:
    """First available SYCL compile command prefix, or None."""
    for _name, cmd in _TOOLCHAIN_CANDIDATES:
        if shutil.which(cmd[0]) is not None:
            return cmd
    return None


def check_l1(src: str, *, timeout: int = 300,
             expected_stdout: str = "PASSED") -> dict:
    """Compile the self-test with a SYCL toolchain and run it.

    Pass criterion: exit code 0 AND `expected_stdout` in the program output
    (our translation contract requires main() to print a PASSED marker).
    Returns {"level": "L1", "passed": bool|None, "status": str, "log": str};
    passed is None with status "sycl_toolchain_missing" when no toolchain
    is installed (mirrors rtl/verify.py's iverilog_missing handling).
    """
    cmd_prefix = sycl_toolchain()
    if cmd_prefix is None:
        return {"level": "L1", "passed": None, "status": "sycl_toolchain_missing",
                "log": "no icpx/dpcpp/clang++ -fsycl on PATH"}

    with tempfile.TemporaryDirectory(prefix="sycl_l1_") as td:
        src_path = Path(td) / "kernel.cpp"
        bin_path = Path(td) / "kernel.bin"
        src_path.write_text(src, encoding="utf-8")
        comp_cmd = [*cmd_prefix, "-std=c++17", "-O2",
                    str(src_path), "-o", str(bin_path)]
        try:
            comp = subprocess.run(comp_cmd, capture_output=True, text=True,
                                  timeout=timeout)
        except subprocess.TimeoutExpired:
            return {"level": "L1", "passed": False, "status": "compile_timeout",
                    "log": " ".join(comp_cmd)}
        if comp.returncode != 0:
            return {"level": "L1", "passed": False, "status": "compile_error",
                    "log": (comp.stderr or comp.stdout or "")[-2000:]}
        try:
            run = subprocess.run([str(bin_path)], capture_output=True, text=True,
                                 timeout=timeout)
        except subprocess.TimeoutExpired:
            return {"level": "L1", "passed": False, "status": "run_timeout", "log": ""}
        log = (run.stdout or "") + (run.stderr or "")
        passed = run.returncode == 0 and expected_stdout in log
        return {"level": "L1", "passed": passed,
                "status": "ok" if passed else "run_failed",
                "log": log[-2000:]}


def verify_sycl(src: str, *, timeout: int = 300) -> dict:
    """Combined verdict: {"l0": ..., "l1": ..., "accepted": bool}."""
    l0 = check_l0(src)
    l1 = check_l1(src, timeout=timeout) if l0["passed"] else {
        "level": "L1", "passed": None, "status": "skipped_l0_failed", "log": ""}
    accepted = l0["passed"] and (l1["passed"] is True or l1["passed"] is None)
    return {"l0": l0, "l1": l1, "accepted": accepted}


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("source", help="SYCL C++ source file")
    args = ap.parse_args()

    src = Path(args.source).read_text(encoding="utf-8")
    res = verify_sycl(src)
    print(f"L0: passed={res['l0']['passed']}")
    for e in res["l0"]["errors"]:
        print(f"  L0 error: {e}")
    print(f"L1: passed={res['l1']['passed']} status={res['l1']['status']}")
    if res["l1"]["log"]:
        print(res["l1"]["log"][-500:])
    print(f"accepted={res['accepted']}")
    sys.exit(0 if res["accepted"] else 1)


if __name__ == "__main__":
    main()
