from __future__ import annotations

import argparse
import json
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

import corpus  # noqa: E402
import sycl_verify  # noqa: E402
from common import schema, teacher_client  # noqa: E402

DOMAIN = "kernel_translate"
TASK_TYPE = "cuda_to_sycl"

SYSTEM_PROMPT = (
    "You are an expert GPU kernel engineer porting CUDA kernels to SYCL 2020 "
    "for Intel XPU (GPU) targets. Your output must compile with `icpx -fsycl`."
)

PORTING_RULES = """\
SYCL 2020 porting contract (follow exactly):
1. A single self-contained C++ translation unit including <sycl/sycl.hpp>;
   it must compile with `icpx -fsycl -std=c++17 -O2`.
2. Use a sycl::queue (prefer sycl::gpu_selector_v with a graceful fallback)
   and sycl::parallel_for for every kernel. Map CUDA thread blocks to
   nd_range work-groups and threads to work-items where the original
   blocking structure matters; a flat range is fine for elementwise kernels.
3. Memory model: choose EXACTLY ONE of (a) USM via sycl::malloc_shared /
   sycl::free, or (b) sycl::buffer + sycl::accessor -- and use it
   consistently for all device data.
4. Include a self-contained `int main()` self-test: allocate inputs, run the
   kernel on the queue, compare against a CPU reference loop with a numeric
   tolerance assert (abs err <= 1e-4), print "SYCL self-test PASSED" on
   success, and return non-zero on any failure.
5. No CUDA constructs may remain: no __global__/__device__, blockIdx /
   threadIdx / blockDim, cudaMalloc/cudaMemcpy, and no <<< >>> launches.
6. Reason first (work-group mapping, memory model choice, numerics), then
   emit the code in a single ```cpp fence."""

_CODE_FENCE_RE = re.compile(r"```(?:cpp|c\+\+|c)?\s*\n(.*?)```", re.DOTALL)


def extract_code(text: str) -> str:
    """Pull the first cpp code fence out of a teacher completion."""
    m = _CODE_FENCE_RE.search(text)
    return m.group(1).strip() if m else text.strip()


def build_porting_prompt(record: corpus.KernelRecord) -> list[dict[str, str]]:
    desc = record.meta.get("description", "")
    user_parts = []
    if desc:
        user_parts.append(f"Task: {desc}\n")
    user_parts.append(
        f"CUDA kernel to port:\n```cpp\n{record.source_code.strip()}\n```\n")
    user_parts.append(
        "PyTorch reference (the semantics the SYCL kernel must reproduce):\n"
        f"```python\n{record.reference_code.strip()}\n```\n")
    user_parts.append(
        f"{PORTING_RULES}\n\nPort the CUDA kernel above to SYCL 2020 now.")
    return [
        {"role": "system", "content": SYSTEM_PROMPT},
        {"role": "user", "content": "\n".join(user_parts)},
    ]


# ---------------------------------------------------------------------------
# Dry-run mock teacher: 2 hand-written (cuda, sycl) pairs (USM style)
# ---------------------------------------------------------------------------

_MOCK_SYCL: dict[str, dict[str, str]] = {}

_MOCK_SYCL["builtin_vector_add"] = {
    "reasoning": (
        "The CUDA kernel is elementwise with a bounds check, so a flat "
        "sycl::range over n with one work-item per element is the natural "
        "port. I use USM (malloc_shared) consistently for A, B and C, and a "
        "CPU loop in main() as the numeric oracle."),
    "code": r'''\
#include <sycl/sycl.hpp>

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <vector>

int main() {
    const int n = 1 << 20;
    sycl::queue q{sycl::gpu_selector_v, [](sycl::exception_list el) {
                      for (auto &e : el) std::rethrow_exception(e);
                  }};
    std::printf("device: %s\n",
                q.get_device().get_info<sycl::info::device::name>().c_str());

    float *A = sycl::malloc_shared<float>(n, q);
    float *B = sycl::malloc_shared<float>(n, q);
    float *C = sycl::malloc_shared<float>(n, q);
    if (!A || !B || !C) {
        std::fprintf(stderr, "USM allocation failed\n");
        return 2;
    }
    std::vector<float> ref(n);
    for (int i = 0; i < n; ++i) {
        A[i] = std::sin(0.001f * static_cast<float>(i));
        B[i] = std::cos(0.002f * static_cast<float>(i));
        ref[i] = A[i] + B[i];
    }

    q.parallel_for(sycl::range<1>(n), [=](sycl::id<1> i) {
         C[i] = A[i] + B[i];
     }).wait();

    double max_err = 0.0;
    for (int i = 0; i < n; ++i) {
        max_err = std::fmax(max_err, std::fabs(C[i] - ref[i]));
    }
    sycl::free(A, q);
    sycl::free(B, q);
    sycl::free(C, q);

    if (max_err > 1e-4) {
        std::fprintf(stderr, "FAILED: max_err=%g\n", max_err);
        return 1;
    }
    std::printf("SYCL self-test PASSED (max_err=%g)\n", max_err);
    return 0;
}
''',
}

_MOCK_SYCL["builtin_sgemv"] = {
    "reasoning": (
        "The CUDA kernel assigns one thread per output row with an inner "
        "fp32 accumulation loop. In SYCL I keep that mapping with a flat "
        "range over m rows (the row loop is short enough not to need "
        "work-group cooperation) and USM shared allocations for A, x, y."),
    "code": r'''\
