#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <vector>

int main() {
    const int m = 512, n = 384;
    sycl::queue q{sycl::gpu_selector_v, [](sycl::exception_list el) {
                      for (auto &e : el) std::rethrow_exception(e);
                  }};
    std::printf("device: %s\n",
                q.get_device().get_info<sycl::info::device::name>().c_str());

    float *A = sycl::malloc_shared<float>(m * n, q);
    float *x = sycl::malloc_shared<float>(n, q);
    float *y = sycl::malloc_shared<float>(m, q);
    if (!A || !x || !y) {
        std::fprintf(stderr, "USM allocation failed\n");
        return 2;
